import json

def merge_arrays(a, b):
    result = []
    seen = []
    for item in a:
        result.append(item)
        seen.append(item)
    for item in b:
        if item not in seen:
            result.append(item)
            seen.append(item)
    return result

def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = dict(a)
        for key, value in b.items():
            if key in result:
                result[key] = deep_merge(result[key], value)
            else:
                result[key] = value
        return result
    elif isinstance(a, list) and isinstance(b, list):
        return merge_arrays(a, b)
    else:
        return b

