import { readFileSync } from 'fs';

const LOG_FILE_PATH = '/tmp/…/app.log';

try {
  const content = readFileSync(LOG_FILE_PATH, 'utf-8');
  const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');

  const levelCounts = new Map<string, number>();
  const componentErrorCounts = new Map<string, number>();
  const errorMessages = new Set<string>();
  const hourlyCounts = new Map<string, number>();

  const regex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)$/;

  for (const line of lines) {
    const match = line.match(regex);
    if (match) {
      const [, timestamp, level, component, message] = match;

      // Count levels
      levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

      // Extract hour
      const hour = timestamp.substring(11, 13);
      const hourStr = `${hour}:00`;
      hourlyCounts.set(hourStr, (hourlyCounts.get(hourStr) || 0) + 1);

      // Track errors
      if (level === 'ERROR') {
        componentErrorCounts.set(component, (componentErrorCounts.get(component) || 0) + 1);
        errorMessages.add(message);
      }
    }
  }

  // Sort levels alphabetically
  const sortedLevels = Array.from(levelCounts.entries())
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([level, count]) => `  ${level}: ${count}`);

  // Find component with most errors
  let mostErrorComponent = 'None';
  let maxErrorCount = 0;
  if (componentErrorCounts.size > 0) {
    const maxCount = Math.max(...componentErrorCounts.values());
    const candidates = Array.from(componentErrorCounts.entries())
      .filter(([_, count]) => count === maxCount)
      .sort((a, b) => a[0].localeCompare(b[0]));
    mostErrorComponent = candidates[0][0];
    maxErrorCount = maxCount;
  }

  // Sort error messages
  const sortedErrorMessages = Array.from(errorMessages).sort((a, b) => a.localeCompare(b));

  // Find busiest hour
  let busiestHour = '00:00';
  let maxHourCount = 0;
  if (hourlyCounts.size > 0) {
    const maxCount = Math.max(...hourlyCounts.values());
    const candidates = Array.from(hourlyCounts.entries())
      .filter(([_, count]) => count === maxCount)
      .sort((a, b) => a[0].localeCompare(b[0]));
    busiestHour = candidates[0][0];
    maxHourCount = maxCount;
