import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.HashMap;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/employees.csv";

        Map<String, Double> deptSum = new HashMap<>();
        Map<String, Integer> deptCount = new HashMap<>();
        double totalSalarySum = 0.0;
        String highestPaidName = "";
        double highestPaidSalary = -1;
        boolean hasEmployees = false;

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            boolean firstLine = true;

            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                if (firstLine) {
                    firstLine = false;
                    continue;
                }

                String[] parts = line.split(",");
                if (parts.length < 4) continue;

                String dept = parts[2].trim();
                String name = parts[1].trim();
                double salary = 0.0;

                try {
                    salary = Double.parseDouble(parts[3].trim());
                } catch (NumberFormatException e) {
                    continue;
                }

                hasEmployees = true;
                totalSalarySum += salary;

                deptSum.put(dept, deptSum.getOrDefault(dept, 0.0) + salary);
                deptCount.put(dept, deptCount.getOrDefault(dept, 0) + 1);

                if (salary > highestPaidSalary) {
                    highestPaidSalary = salary;
                    highestPaidName = name;
                }
            }
        } catch (IOException e) {
            return;
        }

        if (!hasEmployees) {
            return;
        }

        List<String> sortedDepts = new ArrayList<>(deptSum.keySet());
        Collections.sort(sortedDepts);

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (String dept : sortedDepts) {
            double avg = deptSum.get(dept) / deptCount.get(dept);
            System.out.println("  Department: " + String.format(Locale.US, "$%,.2f", avg));
        }
        System.out.println();
        System.out.println("Highest Paid: " + highestPaidName + " (" + String.format(Locale.US, "$%,.0f", Math.round(highestPaidSalary)) + ")");
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (String dept : sortedDepts) {
            if (deptCount.get(dept) > 2) {
                System.out.println("  " + dept + " (" + deptCount.get(dept) + " employees)");
            }
        }
        System.out.println();
        System.out.println("Total Budget: " + String.format(Locale.US, "$%,.0f", Math.round(totalSalarySum)));
    }
}

