import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";

        Map<String, Integer> levels = new TreeMap<>();
        Map<String, Integer> errorComponents = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<Integer, Integer> hours = new TreeMap<>();

        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.*)$");

        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                Matcher matcher = pattern.matcher(line);
                if (matcher.find()) {
                    String level = matcher.group(2);
                    String component = matcher.group(3);
                    String message = matcher.group(4);
                    String timestamp = matcher.group(1);

                    levels.put(level, levels.getOrDefault(level, 0) + 1);

                    int hour = Integer.parseInt(timestamp.substring(11, 13));
                    hours.put(hour, hours.getOrDefault(hour, 0) + 1);

                    if ("ERROR".equals(level)) {
                        errorComponents.put(component, errorComponents.getOrDefault(component, 0) + 1);
                        errorMessages.add(message);
                    }
                }
            }
        } catch (IOException e) {
            // File read error handled gracefully by not printing extra output
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();

        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levels.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String mostErrorComponent = "None";
        int maxErrors = 0;
        if (!errorComponents.isEmpty()) {
            int maxCount = 0;
            String bestComponent = null;
            for (Map.Entry<String, Integer> entry : errorComponents.entrySet()) {
                int count = entry.getValue();
                if (count > maxCount) {
                    maxCount = count;
                    bestComponent = entry.getKey();
                } else if (count == maxCount) {
                    if (bestComponent == null || entry.getKey().compareTo(bestComponent) < 0) {
                        bestComponent = entry.getKey();
                    }
                }
            }
            if (bestComponent != null) {
                mostErrorComponent = bestComponent;
                maxErrors = maxCount;
            }
        }
        System.out.println("Component with Most Errors: " + mostErrorComponent + " (" + maxErrors + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : errorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        int busiestHour = 0;
        int maxEntries = 0;
        if (!hours.isEmpty()) {
            int maxCount = 0;
            int maxHour = 0;
            for (Map.Entry<Integer, Integer> entry : hours.entrySet()) {
                if (entry.getValue() > maxCount) {
                    maxCount = entry.getValue();
                    maxHour = entry.getKey();
                }
            }
            busiestHour = maxHour;
            maxEntries = maxCount;
        }
        System.out.println("Busiest Hour: " + String.format("%02d:00", busiestHour) + " (" + maxEntries + " entries)");
    }
}

import { readFileSync } from 'fs';

const filePath = '/tmp/…/employees.csv';

const content = readFileSync(filePath, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

// Skip header
const dataLines = lines.slice(1);

interface Employee {
  name: string;
  department: string;
  salary: number;
}

const employees: Employee[] = [];
for (const line of dataLines) {
  const cols = line.split(',');
  if (cols.length >= 4) {
    employees.push({
      name: cols[1].trim(),
      department: cols[2].trim(),
      salary: parseFloat(cols[3].trim()) || 0
    });
  }
}

// Aggregations
const deptSalaries: Map<string, number[]> = new Map();
const deptCounts: Map<string, number> = new Map();
let totalBudget = 0;
let highestPaid: { name: string; salary: number } | undefined = undefined;

for (const emp of employees) {
  const dept = emp.department;
  if (!deptSalaries.has(dept)) {
    deptSalaries.set(dept, []);
    deptCounts.set(dept, 0);
  }
  deptSalaries.get(dept)!.push(emp.salary);
  deptCounts.set(dept, deptCounts.get(dept)! + 1);
  totalBudget += emp.salary;

  if (highestPaid === undefined || emp.salary > highestPaid.salary) {
    highestPaid = { name: emp.name, salary: emp.salary };
  }
}

// Formatting
const formatInt = (val: number) => '$' + new Intl.NumberFormat('en-US').format(Math.round(val));
const formatAvg = (val: number) => '$' + new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(val);

// Output
console.log('=== Salary Report ===');
console.log('');
console.log('Average Salary by Department:');

const sortedDepts = Array.from(deptSalaries.keys()).sort();
for (const dept of sortedDepts) {
  const salaries = deptSalaries.get(dept)!;
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  console.log(`  Department: ${formatAvg(avg)}`);
}

console.log('');
console.log(`Highest Paid: ${highestPaid?.name} (${formatInt(highestPaid?.salary || 0)})`);

console.log('');
console.log('Departments with >2 employees:');
const largeDepts = Array.from(deptCounts.entries())
  .filter(([, count]) => count > 2)
  .map(([dept, count]) => ({ dept, count }))
  .sort((a, b) => a.dept.localeCompare(b.dept));

for (const item of largeDepts) {
  console.log(`  ${item.dept} (${item.count} employees)`);
}

console.log('');
console.log(`Total Budget: ${formatInt(totalBudget)}`);

