import Foundation

let filePath = "/tmp/…/app.log"

var levelCounts: [String: Int] = [:]
var componentErrorCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

do {
    let content = try String(contentsOfFile: filePath, encoding: .utf8)
    let lines = content.components(separatedBy: .newlines)

    let pattern = #"\[(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)"#
    let regex = try NSRegularExpression(pattern: pattern, options: [])

    for line in lines {
        if line.isEmpty { continue }
        let range = NSRange(line.startIndex..., in: line)
        if let match = regex.firstMatch(in: line, options: [], range: range) {
            let timeRange = match.range(at: 2)
            let levelRange = match.range(at: 3)
            let componentRange = match.range(at: 4)
            let messageRange = match.range(at: 5)

            // Convert NSRange to Range<String.Index>
            let timeStart = line.index(line.startIndex, offsetBy: timeRange.location)
            let timeEnd = line.index(line.startIndex, offsetBy: timeRange.location + timeRange.length)
            let levelStart = line.index(line.startIndex, offsetBy: levelRange.location)
            let levelEnd = line.index(line.startIndex, offsetBy: levelRange.location + levelRange.length)
            let componentStart = line.index(line.startIndex, offsetBy: componentRange.location)
            let componentEnd = line.index(line.startIndex, offsetBy: componentRange.location + componentRange.length)
            let messageStart = line.index(line.startIndex, offsetBy: messageRange.location)
            let messageEnd = line.index(line.startIndex, offsetBy: messageRange.location + messageRange.length)

            let time = String(line[timeStart..<timeEnd])
            let level = String(line[levelStart..<levelEnd])
            let component = String(line[componentStart..<componentEnd])
            let message = String(line[messageStart..<messageEnd]).trimmingCharacters(in: .whitespacesAndNewlines)

            levelCounts[level, default: 0] += 1

            let hour = String(time.prefix(2))
            hourCounts["\(hour):00", default: 0] += 1

            if level == "ERROR" {
                componentErrorCounts[component, default: 0] += 1
                errorMessages.insert(message)
            }
        }
    }
} catch {
    // If file reading fails, stats remain empty
}

print("=== Log Analysis ===")
print("")

print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level] ?? 0)")
}

print("")

var maxErrors = 0
var maxComponent = "None"
for (comp, count) in componentErrorCounts {
    if count > maxErrors {
        maxErrors = count
        maxComponent = comp
    } else if count == maxErrors && count > 0 {
        if comp < maxComponent {
            maxComponent = comp
        }
    }
}
print("Component with Most Errors: \(maxComponent) (\(maxErrors) errors)")

print("")

print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}

print("")

var maxEntries = 0
var busiestHour = "00:00"
for hour in hourCounts.keys.sorted() {
    let count = hourCounts[hour] ?? 0
    if count > maxEntries {
        maxEntries = count
        busiestHour = hour
    }
}
print("Busiest Hour: \(busiestHour) (\(maxEntries) entries)")

