fn format_int_commas(n: i64) -> String {
    if n == 0 {
        return "0".to_string();
    }
    let sign = if n < 0 { "-" } else { "" };
    let n = n.abs();
    let s = n.to_string();
    let mut chars: Vec<char> = s.chars().rev().collect();
    let mut res = String::new();
    let mut count = 0;
    for c in chars {
        if count > 0 && count % 3 == 0 {
            res.push(',');
        }
        res.push(c);
        count += 1;
    }
    format!("{}{}", sign, res.chars().rev().collect::<String>())
}

fn format_currency_float(n: f64) -> String {
    let sign = if n < 0.0 { "-" } else { "" };
    let n = n.abs();
    let s = format!("{:.2}", n);
    let parts: Vec<&str> = s.split('.').collect();
    let int_part = parts[0];
    let dec_part = if parts.len() > 1 { parts[1] } else { "00" };
    let formatted_int = format_int_commas(int_part.parse::<i64>().unwrap());
    format!("{}{}{}", sign, formatted_int, dec_part)
}

