import Foundation

func serialize(_ value: Any) -> String {
    do {
        let data = try JSONSerialization.data(withJSONObject: value, options: [])
        return String(data: data, encoding: .utf8) ?? ""
    } catch {
        return ""
    }
}

func merge(_ a: Any, _ b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result = dictA
        for (key, value) in dictB {
            if let existing = dictA[key] {
                result[key] = merge(existing, value)
            } else {
                result[key] = value
            }
        }
        return result
    } else if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result = arrA
        var seen: Set<String>
        for item in arrA {
            seen.add(serialize(item))
        }
        for item in arrB {
            let s = serialize(item)
            if !seen.contains(s) {
                result.append(item)
                seen.add(s)
            }
        }
        return result
    } else {
        return b
    }
}

func sortKeys(_ value: Any) -> Any {
    if let dict = value as? [String: Any] {
        var sorted = [String: Any]()
        for key in dict.keys.sorted() {
            sorted[key] = sortKeys(dict[key])
        }
        return sorted
    } else if let arr = value as? [Any] {
        return arr.map { sortKeys($0) }
    } else {
        return value
    }
}

