          let jsonB = try? JSONSerialization.jsonObject(with: dataB, options: .mutableContainers) else {
        return
    }

    let merged = merge(jsonA, jsonB)
    let sorted = sortKeys(merged)

    do {
        let output = try JSONSerialization.data(withJSONObject: sorted, options: [.prettyPrinted])
        print(String(data: output, encoding: .utf8)!)
    } catch {
        // Ignore
    }
}

