                if dist[current] != .infinity && dist[neighbor]! > dist[current]! + edge.weight {
                    dist[neighbor] = dist[current]! + edge.weight
                }
            }
        }
    }
    return dist
}

func formatDistance(_ d: Double) -> String {
    if d == .infinity { return "Infinity" }
    if d == 0.0 { return "0" }
    if d.truncatingRemainder(dividingBy: 1) == 0 { return "\(Int(d))" }
    return "\(d)"
}

do {
    let graph = try readGraph()

    var adj: [String: [(String, Double)]] = [:]
    for node in graph.nodes {
        adj[node] = []
    }

    for edge in graph.edges {
        adj[edge.from] = (adj[edge.from] ?? []) + [(edge.to, edge.weight)]
        adj[edge.to] = (adj[edge.to] ?? []) + [(edge.from, edge.weight)]
    }

    let startNode = "A"
    var dist: [String: Double] = [:]
    for node in graph.nodes {
        dist[node] = .infinity
    }
    dist[startNode] = 0.0

    var unvisited = Set(graph.nodes)

    while !unvisited.isEmpty {
        var u: String?
        var minDist: Double = .infinity

        for node in unvisited {
            let d = dist[node] ?? .infinity
            if d < minDist {
                minDist = d
                u = node
            }
        }

        if u == nil || minDist == .infinity {
            break
        }

        let current = u!
        unvisited.remove(current)

        if let neighbors = adj[current] {
            for (neighbor, weight) in neighbors {
                if dist[current]! + weight < dist[neighbor]! {
                    dist[neighbor] = dist[current]! + weight
                }
            }
        }
    }

    print("=== Shortest Paths from A ===")
    print()

    let sortedNodes = dist.keys.sorted()
    for node in sortedNodes {
        print("A -> \(node): \(formatDistance(dist[node] ?? .infinity))")
    }
} catch {
    print("Error: \(error)")
}

use std::collections::{BTreeMap, HashSet};
use std::fs;

fn main() {
    let path = "/tmp/…/app.log";
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Error reading file: {}", e);
            return;
        }
    };

    let mut level_counts: BTreeMap<String, u64> = BTreeMap::new();
    let mut component_errors: BTreeMap<String, u64> = BTreeMap::new();
    let mut error_messages: HashSet<String> = HashSet::new();
    let mut hour_counts: BTreeMap<u32, u64> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        if let Some(bracket_idx) = line.find(']') {
            let ts = &line[..bracket_idx + 1];
            let parts_ts: Vec<&str> = ts.split_whitespace().collect();
            if parts_ts.len() < 2 {
                continue;
            }
            let time_str = parts_ts[1];
            let hour_str = time_str.split(':').next().unwrap_or("");
            let hour: u32 = match hour_str.parse() {
                Ok(h) => h,
                Err(_) => continue,
            };

            let rest = &line[bracket_idx + 2..];
            let parts_rest: Vec<&str> = rest.split_whitespace().collect();

            if parts_rest.len() < 3 {
                continue;
            }

            let level = parts_rest[0];
            let component_part = parts_rest[1];
            let dash = parts_rest[2];

            if dash != "-" {
                continue;
            }

            let component = component_part.trim_start_matches('(').trim_end_matches(')');

            let message: String = parts_rest[3..].iter().collect();

            *level_counts.entry(level.to_string()).or_insert(0) += 1;

            if level == "ERROR" {
                *component_errors.entry(component.to_string()).or_insert(0) += 1;
                error_messages.insert(message.clone());
            }

            *hour_counts.entry(hour).or_insert(0) += 1;
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let mut max_errors = 0u64;
    let mut max_component = String::new();
    if !component_errors.is_empty() {
        let mut sorted_errs: Vec<_> = component_errors.iter().collect();
        sorted_errs.sort_by(|a, b| {
            match b.1.cmp(a.1) {
                std::cmp::Ordering::Equal => a.0.cmp(b.0),
                other => other,
            }
        });
        if !sorted_errs.is_empty() {
            let (comp, count) = sorted_errs[0];
            max_component = comp.clone();
            max_errors = count;
        }
    }
    println!("Component with Most Errors: {}", if max_component.is_empty() { "None (0 errors)" } else { &format!("{} ({})", max_component, max_errors) });
    println!();
    println!("Unique Error Messages:");
    let mut sorted_msgs: Vec<_> = error_messages.iter().collect();
    sorted_msgs.sort();
    for msg in sorted_msgs {
        println!("  - {}", msg);
    }
    println!();

    let mut max_hour_entries = 0u64;
    let mut busiest_hour = 0u32;
    if !hour_counts.is_empty() {
        let mut sorted_hours: Vec<_> = hour_counts.iter().collect();
        sorted_hours.sort_by(|a, b| {
            match b.1.cmp(a.1) {
                std::cmp::Ordering::Equal => a.0.cmp(b.0),
                other => other,
            }
        });
        if !sorted_hours.is_empty() {
            let (hour, count) = sorted_hours[0];
            busiest_hour = *hour;
            max_hour_entries = count;
        }
    }
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, max_hour_entries);
}

