    int hour;
    int count;
} HourEntry;

static LevelEntry *levels = NULL;
static size_t levels_capacity = 0;
static size_t levels_count = 0;

static ComponentEntry *components = NULL;
static size_t components_capacity = 0;
static size_t components_count = 0;

static MsgEntry *messages = NULL;
static size_t messages_capacity = 0;
static size_t messages_count = 0;

static HourEntry *hours = NULL;
static size_t hours_count = 0; // 0 to 23

static char *my_strdup(const char *s) {
    size_t len = strlen(s);
    char *p = malloc(len + 1);
    if (!p) return NULL;
    memcpy(p, s, len + 1);
    return p;
}

static int cmp_level(const void *a, const void *b) {
    const LevelEntry *la = (const LevelEntry *)a;
    const LevelEntry *lb = (const LevelEntry *)b;
    return strcmp(la->name, lb->name);
}

