}

int main(void) {
    FILE *f = fopen("/tmp/…/app.log", "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t nread;

    // Initialize hours
    hours = malloc(24 * sizeof(HourEntry));
    if (!hours) {
        perror("malloc hours");
        fclose(f);
        return 1;
    }
    for (int i = 0; i < 24; i++) {
        hours[i].hour = i;
        hours[i].count = 0;
    }

    while ((nread = getline(&line, &len, f)) != -1) {
        int y, m, d, h, mi, s;
        char lvl_buf[32], comp_buf[32], msg_buf[4096];

        // Pattern: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        // sscanf format: "[%d-%d-%d %d:%d:%d] %31[^ ] (%31[^ ] ) - %n"
        // Wait, %n is not char. Use %[^\n] for message.
        // Need to match space after ) and space before -
        // Format: ... ] LEVEL (COMP) - MSG
        // sscanf: "[%d-%d-%d %d:%d:%d] %31[^ ] (%31[^ ] ) - %[^\n]"
        // This expects space after ) in format string to consume the space before -.
        // Actually, the log format is "(component) - message".
        // So ")" then " " then "-" then " " then "message".
        // sscanf format: " (%31[^ ] ) - %[^\n]"
        // Matches " (" then component then " ) " then "-" then " " then message.
        // Wait, sscanf format string literal matches characters.
        // " (%31[^ ] ) - %[^\n]"
        // Matches: space, (, component, space, ), space, -, space, message.
        // Correct.

        int ret = sscanf(line, "[%d-%d-%d %d:%d:%d] %31[^ ] (%31[^ ] ) - %[^\n]",
                         &y, &m, &d, &h, &mi, &s, lvl_buf, comp_buf, msg_buf);

        if (ret != 9) continue;

        // Update hour count
        hours[h].count++;

        // Check Level
        int found_level = 0;
        for (size_t i = 0; i < levels_count; i++) {
            if (strcmp(levels[i].name, lvl_buf) == 0) {
                levels[i].count++;
                found_level = 1;
                break;
            }
        }
        if (!found_level) {
            if (levels_count >= levels_capacity) {
                levels_capacity = levels_capacity == 0 ? 100 : levels_capacity * 2;
                levels = realloc(levels, levels_capacity * sizeof(LevelEntry));
            }
            levels[levels_count].name = my_strdup(lvl_buf);
            levels[levels_count].count = 1;
            levels_count++;
        }

        // Check Component (only for ERROR)
        // Note: "Errors" implies LEVEL == "ERROR".
        // Check message uniqueness (only for ERROR)
        // Wait, "Unique Error Messages" implies filtering by ERROR level.
        // "Component with Most Errors" implies filtering by ERROR level.
        // "Entries by Level" implies all levels.
        // "Busiest Hour" implies all entries.

        if (strcmp(lvl_buf, "ERROR") == 0) {
            // Component
            int found_comp = 0;
            for (size_t i = 0; i < components_count; i++) {
                if (strcmp(components[i].name, comp_buf) == 0) {
                    components[i].count++;
                    found_comp = 1;
                    break;
                }
            }
            if (!found_comp) {
                if (components_count >= components_capacity) {
                    components_capacity = components_capacity == 0 ? 100 : components_capacity * 2;
                    components = realloc(components, components_capacity * sizeof(ComponentEntry));
                }
                components[components_count].name = my_strdup(comp_buf);
                components[components_count].count = 1;
                components_count++;
            }

            // Message
            int found_msg = 0;
            for (size_t i = 0; i < messages_count; i++) {
                if (strcmp(messages[i].msg, msg_buf) == 0) {
                    found_msg = 1;
                    break;
                }
            }
            if (!found_msg) {
                if (messages_count >= messages_capacity) {
                    messages_capacity = messages_capacity == 0 ? 100 : messages_capacity * 2;
                    messages = realloc(messages, messages_capacity * sizeof(MsgEntry));
                }
                messages[messages_count].msg = my_strdup(msg_buf);
                messages_count++;
            }
        }
    }
    free(line);
    fclose(f);

    // Sort and Print
    qsort(levels, levels_count, sizeof(LevelEntry), cmp_level);

    printf("=== Log Analysis ===\n\n");
    printf("Entries by Level:\n");
    for (size_t i = 0; i < levels_count; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");

    // Component with Most Errors
    ComponentEntry *max_comp = NULL;
    int max_count = -1;
    // Sort components alphabetically to handle ties
    qsort(components, components_count, sizeof(ComponentEntry), cmp_component);
    for (size_t i = 0; i < components_count; i++) {
        if (components[i].count > max_count) {
            max_count = components[i].count;
            max_comp = &components[i];
        }
    }
    if (max_comp) {
        printf("Component with Most Errors: %s (%d errors)\n", max_comp->name, max_comp->count);
    } else {
        printf("Component with Most Errors: None (0 errors)\n");
    }
    printf("\n");

    // Unique Error Messages
    qsort(messages, messages_count, sizeof(MsgEntry), cmp_msg);
    printf("Unique Error Messages:\n");
    for (size_t i = 0; i < messages_count; i++) {
        printf("  - %s\n", messages[i].msg);
    }
    printf("\n");

    // Busiest Hour
    HourEntry *max_hour = &hours[0];
    for (int i = 1; i < 24; i++) {
        if (hours[i].count > max_hour->count) {
            max_hour = &hours[i];
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", max_hour->hour, max_hour->count);

    // Cleanup
    for (size_t i = 0; i < levels_count; i++) free(levels[i].name);
    free(levels);
    for (size_t i = 0; i < components_count; i++) free(components[i].name);
    free(components);
    for (size_t i = 0; i < messages_count; i++) free(messages[i].msg);
    free(messages);
    free(hours);

    return 0;
}

