import { readFileSync } from 'fs';

const GRAPH_PATH = '/tmp/…/graph.json';

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface GraphData {
  nodes: string[];
  edges: Edge[];
}

// Read and parse the JSON file
const rawData = readFileSync(GRAPH_PATH, 'utf-8');
const data: GraphData = JSON.parse(rawData);

// Build adjacency list
const adj: Map<string, Array<{ to: string; weight: number }>> = new Map();

for (const node of data.nodes) {
  adj.set(node, []);
}

for (const edge of data.edges) {
  const { from, to, weight } = edge;
  adj.get(from)!.push({ to, weight });
  adj.get(to)!.push({ from, weight }); // Undirected
}

// Dijkstra's Algorithm
const startNode = 'A';
const distances = new Map<string, number>();
const visited = new Set<string>();

// Initialize distances
for (const node of data.nodes) {
  distances.set(node, Infinity);
}
distances.set(startNode, 0);

// Helper to find unvisited node with minimum distance
function getUnvisitedMin(): string | undefined {
  let minNode = undefined;
  let minDist = Infinity;
  for (const node of data.nodes) {
    if (!visited.has(node)) {
      const dist = distances.get(node);
      if (dist !== undefined && dist < minDist) {
        minDist = dist;
        minNode = node;
      }
    }
  }
  return minNode;
}

while (true) {
  const current = getUnvisitedMin();
  if (!current) break;

  visited.add(current);
  const currentDist = distances.get(current)!;

  for (const neighbor of adj.get(current)!) {
    const { to, weight } = neighbor;
    const newDist = currentDist + weight;
    if (newDist < distances.get(to)!) {
      distances.set(to, newDist);
    }
  }
}

// Sort nodes alphabetically
const sortedNodes = [...data.nodes].sort();

// Output
console.log('=== Shortest Paths from A ===');
console.log('');

for (const node of sortedNodes) {
  const dist = distances.get(node);
  const distStr = dist === Infinity ? 'Infinity' : dist.toString();
  console.log(`A -> ${node}: ${distStr}`);
}

