use std::collections::BTreeMap;
use std::fs;
use std::io;
use std::path::Path;

fn main() -> io::Result<()> {
    let base_dir = "/tmp/…/project_tree";
    let base_path = Path::new(base_dir);

    let mut file_data: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    walk_directory(base_path, &mut file_data)?;

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0u64;
    let mut total_lines = 0u64;
    let mut total_chars = 0u64;

    for (ext, files) in &file_data {
        println!("Extension: {}", ext);

        let mut ext_lines = 0u64;
        let mut ext_chars = 0u64;

        for (rel_path, lines, chars) in files {
            println!("  {}", rel_path);
            println!("    {} lines, {} chars", lines, chars);
            ext_lines += lines;
            ext_chars += chars;
            total_files += 1;
            total_lines += lines;
            total_chars += chars;
        }

        println!("  Files: {}", files.len());
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);

    Ok(())
}

fn walk_directory(dir: &Path, file_data: &mut BTreeMap<String, Vec<(String, u64, u64)>>) -> io::Result<()> {
    let mut entries = fs::read_dir(dir)?;

    while let Some(entry) = entries.next_entry()? {
        let path = entry.path();

        if path.is_dir() {
            walk_directory(&path, file_data)?;
        } else if path.is_file() {
            let extension = get_extension(&path);

            if let Some(ext) = extension {
                let (lines, chars) = count_lines_and_chars(&path)?;

                let relative_path = if let Ok(relative) = path.strip_prefix(dir) {
                    relative.to_string_lossy().into_owned()
                } else {
                    path.to_string_lossy().into_owned()
                };

                file_data.entry(ext).or_insert_with(Vec::new).push((relative, lines, chars));
            }
        }
    }

    Ok(())
}

fn get_extension(path: &Path) -> Option<String> {
    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|s| format!(".{}", s))
}

fn count_lines_and_chars(path: &Path) -> io::Result<(u64, u64)> {
    let content = fs::read_to_string(path)?;
    let lines = content.lines().count();
    let chars = content.len() as u64;

    Ok((lines as u64, chars))
}

