public class Main {
    public static void main(String[] args) {
        int[][] A = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        int[][] B = {
            {9, 8, 7},
            {6, 5, 4},
            {3, 2, 1}
        };

        int[][] C = multiply(A, B);
        int det = determinant(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrixRow(A[0]);
        printMatrixRow(A[1]);
        printMatrixRow(A[2]);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrixRow(B[0]);
        printMatrixRow(B[1]);
        printMatrixRow(B[2]);
        System.out.println();
        System.out.println("A x B =");
        printMatrixRow(C[0]);
        printMatrixRow(C[1]);
        printMatrixRow(C[2]);
        System.out.println();
        System.out.println("Determinant: " + det);
    }

    private static int[][] multiply(int[][] A, int[][] B) {
        int size = A.length;
        int[][] C = new int[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                for (int k = 0; k < size; k++) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }
        return C;
    }

    private static int determinant(int[][] M) {
        int a = M[0][0], b = M[0][1], c = M[0][2];
        int d = M[1][0], e = M[1][1], f = M[1][2];
        int g = M[2][0], h = M[2][1], i = M[2][2];
        return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
    }

    private static void printMatrixRow(int[] row) {
        System.out.printf(Locale.US, "  %4d %4d %4d%n", row[0], row[1], row[2]);
    }
}

import * as fs from 'fs';
