import type { Dirent, Stats } from 'fs';

const TARGET_DIR = '/tmp/…/project_tree';

type FileStats = {
  path: string;
  lines: number;
  chars: number;
};

type ExtensionGroup = {
  extension: string;
  files: FileStats[];
};

async function countLinesAndChars(buffer: Buffer): { lines: number; chars: number } {
  const chars = buffer.length;
  // Count newlines (0x0A) for line count
  // wc -l counts newlines.
  let lines = 0;
  for (const byte of buffer) {
    if (byte === 10) { // \n
      lines++;
    }
  }
  return { lines, chars };
}

async function walkDirectory(dir: string, visitedDirs: Set<string>, files: Map<string, FileStats[]>): Promise<void> {
  try {
    const entries = await fs.promises.readdir(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.posix.join(dir, entry.name);

      if (visitedDirs.has(fullPath)) {
        continue;
      }

      try {
        const stat = await fs.promises.lstat(fullPath);

        if (stat.isSymbolicLink()) {
          continue;
        }

        if (stat.isDirectory()) {
          visitedDirs.add(fullPath);
          await walkDirectory(fullPath, visitedDirs, files);
        } else if (stat.isFile()) {
          const content = await fs.promises.readFile(fullPath);
          const { lines, chars } = await countLinesAndChars(content);
          const relPath = path.posix.relative(dir, fullPath);

          // Ensure relative path is not '.'
          if (relPath === '.') relPath = '';

          const ext = path.posix.extname(entry.name);

          if (!files.has(ext)) {
            files.set(ext, []);
          }
          files.get(ext)!.push({ path: relPath, lines, chars });
        }
      } catch (err) {
        // Skip files that cannot be read or stats retrieved
        console.error(`Error processing ${fullPath}:`, err);
      }
    }
  } catch (err) {
    // Skip directories that cannot be read
    console.error(`Error reading directory ${dir}:`, err);
  }
}

