    const group = filesMap.get(ext)!;
    group.sort((a, b) => a.path.localeCompare(b.path));

    let groupFiles = 0;
    let groupLines = 0;
    let groupChars = 0;

    console.log(`Extension: ${ext}`);
    console.log(`  Files: ${group.length}`);
    console.log(`  Total Lines: ${group.reduce((sum, f) => sum + f.lines, 0)}`);
    console.log(`  Total Characters: ${group.reduce((sum, f) => sum + f.chars, 0)}`);

    for (const file of group) {
      console.log(`    ${file.path}: ${file.lines} lines, ${file.chars} chars`);
    }

    groupFiles = group.length;
    groupLines = group.reduce((sum, f) => sum + f.lines, 0);
    groupChars = group.reduce((sum, f) => sum + f.chars, 0);

    totalFiles += groupFiles;
    totalLines += groupLines;
    totalChars += groupChars;

    if (i < extensions.length - 1) {
      continue;
    }
  }

  console.log('');
  console.log(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);
}

