    // Define Matrix A
    let a = [[1, 2, 3], [4, 5, 6], [7, 8, 9]];

    // Define Matrix B
    let b = [[9, 8, 7], [6, 5, 4], [3, 2, 1]];

    // Compute C = A x B
    let mut c = [[0; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            for k in 0..3 {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }

    // Compute Determinant of C
    // C is 3x3: [[a,b,c], [d,e,f], [g,h,i]]
    let a_val = c[0][0];
    let b_val = c[0][1];
    let c_val = c[0][2];
    let d_val = c[1][0];
    let e_val = c[1][1];
    let f_val = c[1][2];
    let g_val = c[2][0];
    let h_val = c[2][1];
    let i_val = c[2][2];

    let det = a_val * (e_val * i_val - f_val * h_val)
        - b_val * (d_val * i_val - f_val * g_val)
        + c_val * (d_val * h_val - e_val * g_val);

    // Output formatted results
    println!("=== Matrix Operations ===");
