use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead};

fn main() {
    let file = File::open("/tmp/…/graph.json")
        .expect("Failed to open file");
    let reader = io::BufReader::new(file);
    let json = reader.lines().collect::<Result<Vec<String>, _>>().expect("Failed to read file");
    let json_str = json.join("\n");

    let nodes = parse_nodes(&json_str);
    let edges = parse_edges(&json_str);

    let mut adj: HashMap<&str, Vec<(String, i32)>> = HashMap::new();
    for node in &nodes {
        adj.insert(*node, Vec::new());
    }
    for edge in &edges {
        adj.entry(edge.from.as_str()).or_insert_with(Vec::new).push((edge.to.clone(), edge.weight));
        adj.entry(edge.to.as_str()).or_insert_with(Vec::new).push((edge.from.clone(), edge.weight));
    }

    let distances = dijkstra(&nodes, &adj, "A");

    println!("=== Shortest Paths from A ===\n");
    let mut sorted_nodes: Vec<&str> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let dist = distances.get(*node).unwrap_or(&0);
        println!("A -> {}: {}", node, dist);
    }
}

fn parse_nodes(json: &str) -> Vec<String> {
    let mut nodes = Vec::new();
    let mut current = String::new();
    let mut in_array = false;

    for c in json.chars() {
        if c == '[' {
            in_array = true;
            current.clear();
        } else if c == ']' {
            if !current.is_empty() {
                nodes.push(current.trim().to_string());
            }
            in_array = false;
            current.clear();
        } else if in_array && c != ',' && c != ' ' && c != '\n' && c != '\t' {
            current.push(c);
        }
    }
    nodes
}

fn parse_edges(json: &str) -> Vec<Edge> {
    let mut edges = Vec::new();
    let mut in_edges = false;
    let mut edge_from = String::new();
    let mut edge_to = String::new();
    let mut edge_weight = String::new();
    let mut current_key = String::new();
    let mut current_value = String::new();
    let mut in_value = false;

    for c in json.chars() {
        if c == '[' && !in_edges {
            in_edges = true;
            continue;
        }
        if c == ']' {
            in_edges = false;
            continue;
        }
        if in_edges {
            if c == '"' {
                if current_key.is_empty() {
                    if !edge_from.is_empty() {
                        edges.push(Edge { from: edge_from.clone(), to: edge_to.clone(), weight: edge_weight.parse().unwrap_or(0) });
                    }
                    edge_from = String::new();
                    edge_to = String::new();
                    edge_weight = String::new();
                    current_key = String::new();
                    current_value = String::new();
                    in_value = false;
                } else if !current_value.is_empty() {
                    edges.push(Edge { from: edge_from.clone(), to: edge_to.clone(), weight: current_value.parse().unwrap_or(0) });
                    current_value = String::new();
                }
                current_key = String::new();
                in_value = false;
            } else if c == ':' {
                if !current_key.is_empty() {
                    if current_key == "from" {
                        edge_from = current_value.clone();
                    } else if current_key == "to" {
                        edge_to = current_value.clone();
                    } else if current_key == "weight" {
                        edge_weight = current_value.clone();
                    }
                    current_value = String::new();
                }
                in_value = false;
            } else if c == ',' {
                if !current_key.is_empty() {
                    if current_key == "from" {
                        edge_from = current_value.clone();
                    } else if current_key == "to" {
                        edge_to = current_value.clone();
                    } else if current_key == "weight" {
                        edge_weight = current_value.clone();
                    }
                    current_value = String::new();
                    current_key = String::new();
                }
                in_value = false;
            } else if c.is_whitespace() {
                continue;
            } else {
                if in_value {
                    current_value.push(c);
                } else {
                    current_key.push(c);
                }
            }
        }
    }
    edges
}

fn dijkstra(nodes: &[String], adj: &HashMap<&str, Vec<(String, i32)>>, start: &str) -> HashMap<String, i32> {
    let mut distances: HashMap<String, i32> = HashMap::new();
    for node in nodes {
        distances.insert(node.clone(), i32::MAX);
    }
    distances.insert(start.to_string(), 0);

    let mut visited = HashMap::new();

    while distances.values().any(|&d| d != i32::MAX) {
        let mut min_dist = i32::MAX;
        let mut min_node = None;

        for (node, dist) in &distances {
            if *dist != i32::MAX && !visited.contains_key(*node) {
                if *dist < min_dist {
                    min_dist = *dist;
                    min_node = Some(node.clone());
                }
            }
        }

        if min_node.is_none() {
            break;
        }

        let node = min_node.unwrap();
        visited.insert(node.clone());

        if let Some(neighbors) = adj.get(node.as_str()) {
            for (neighbor, weight) in neighbors {
                let new_dist = distances.get(&node).unwrap() + weight;
                if new_dist < distances.get(neighbor).unwrap() {
                    distances.insert(neighbor.clone(), new_dist);
                }
            }
        }
    }

    distances
}

