func multiply(_ a: [[Int]], _ b: [[Int]]) -> [[Int]] {
    let rowsA = a.count
    let colsA = a[0].count
    let colsB = b[0].count
    var result = [[Int]](repeating: [Int](repeating: 0, count: colsB), count: rowsA)
    for i in 0..<rowsA {
        for j in 0..<colsB {
            for k in 0..<colsA {
                result[i][j] += a[i][k] * b[k][j]
            }
        }
    }
    return result
}

func determinant(_ mat: [[Int]]) -> Int {
    let a = mat[0][0], b = mat[0][1], c = mat[0][2]
    let d = mat[1][0], e = mat[1][1], f = mat[1][2]
    let g = mat[2][0], h = mat[2][1], i = mat[2][2]
    return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)
}

